package cn.mop.api;
import cn.mop.domain.Capabilities;
import cn.mop.domain.authorization.CapabilityCatalog;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class CapabilityCatalogTest {
    Map<String,List<String>> declarations(){var result=new LinkedHashMap<String,List<String>>();for(var role:CapabilityCatalog.ROLES)result.put(role.id(),new ArrayList<>(Capabilities.forRole(role.id())));return result;}
    @Test void exactContractFourRolesAndFiveResourceDimensions(){var c=CapabilityCatalog.current();assertEquals(List.of("viewer","tadmin","msp","padmin"),c.roles().stream().map(CapabilityCatalog.Role::id).toList());assertEquals(List.of("资产与指标","告警与工单","模板与自动化","平台管理","成员管理"),c.dimensions().stream().map(CapabilityCatalog.Dimension::label).toList());}
    @Test void everyCurrentCapabilityAppearsExactlyOnceWithActualRoleBits(){var c=CapabilityCatalog.current();Set<String> all=new TreeSet<>();declarations().values().forEach(all::addAll);assertEquals(new ArrayList<>(all),c.entries().stream().map(CapabilityCatalog.Entry::id).toList());for(var entry:c.entries())for(var role:c.roles())assertEquals(Capabilities.forRole(role.id()).contains(entry.id()),entry.declaredByRole().get(role.id()));}
    @Test void emptyDimensionsAreKeptNotSilentlyRemoved(){var input=declarations();input.values().forEach(values->values.removeIf(value->value.startsWith("backup_plan_drafts:")||value.startsWith("inspection_source_collections:")||value.startsWith("inspection_templates:")||value.startsWith("inspection_worksheets:")));var c=CapabilityCatalog.fromDeclarations(input);for(String id:List.of("TEMPLATES_AUTOMATION"))assertTrue(c.dimensions().stream().filter(d->d.id().equals(id)).findFirst().orElseThrow().capabilityIds().isEmpty());assertEquals(5,c.dimensions().size());assertEquals(List.of("contacts:read","contacts:write"),c.dimensions().stream().filter(d->d.id().equals("MEMBER_ADMIN")).findFirst().orElseThrow().capabilityIds());}
    @Test void crossDimensionSearchIsOneEntryAndTwoDimensionReferences(){var c=CapabilityCatalog.current();var entry=c.entries().stream().filter(e->e.id().equals("search:read")).findFirst().orElseThrow();assertEquals(List.of("ASSETS_METRICS","ALERTS_TICKETS"),entry.dimensionIds());assertEquals(2,c.dimensions().stream().filter(d->d.capabilityIds().contains("search:read")).count());}
    @Test void declarationHashIsStableUnderMapAndCapabilityOrder(){var first=declarations();var reversed=new LinkedHashMap<String,List<String>>();var keys=new ArrayList<>(first.keySet());Collections.reverse(keys);for(String key:keys){var values=new ArrayList<>(first.get(key));Collections.reverse(values);reversed.put(key,values);}assertEquals(CapabilityCatalog.fromDeclarations(first).declarationHash(),CapabilityCatalog.fromDeclarations(reversed).declarationHash());assertTrue(CapabilityCatalog.current().declarationHash().matches("[0-9a-f]{64}"));}
    @Test void aChangedDeclarationChangesHashButCannotMutateRuntimeCapabilities(){var input=declarations();String before=CapabilityCatalog.current().declarationHash();input.get("viewer").add("audit:read");assertNotEquals(before,CapabilityCatalog.fromDeclarations(input).declarationHash());assertFalse(Capabilities.forRole("viewer").contains("audit:read"));assertEquals(before,CapabilityCatalog.current().declarationHash());}
    @Test void extraRoleUnclassifiedCapabilityDuplicatesAndMissingRoleFailClosed(){var extra=declarations();extra.put("new-admin",List.of());assertThrows(IllegalArgumentException.class,()->CapabilityCatalog.fromDeclarations(extra));var missing=declarations();missing.remove("viewer");assertThrows(IllegalArgumentException.class,()->CapabilityCatalog.fromDeclarations(missing));var unknown=declarations();unknown.get("padmin").add("secrets:all");assertThrows(IllegalArgumentException.class,()->CapabilityCatalog.fromDeclarations(unknown));var duplicate=declarations();duplicate.get("viewer").add("assets:read");assertThrows(IllegalArgumentException.class,()->CapabilityCatalog.fromDeclarations(duplicate));}
    @Test void outputCollectionsAreImmutableAndUnknownRuntimeRoleStillDenied(){var c=CapabilityCatalog.current();assertThrows(UnsupportedOperationException.class,()->c.entries().clear());assertThrows(UnsupportedOperationException.class,()->c.entries().get(0).declaredByRole().put("viewer",true));assertThrows(UnsupportedOperationException.class,()->c.dimensions().get(0).capabilityIds().clear());assertTrue(Capabilities.forRole("new-admin").isEmpty());}
    @Test void unpublishedBackupAndInspectionCapabilitiesAreClassifiedAndPadminOnly(){var c=CapabilityCatalog.current();assertEquals(List.of("backup_plan_drafts:read","backup_plan_drafts:write","inspection_source_collections:read","inspection_source_collections:write","inspection_templates:read","inspection_templates:write","inspection_worksheets:read","inspection_worksheets:write"),c.dimensions().stream().filter(d->d.id().equals("TEMPLATES_AUTOMATION")).findFirst().orElseThrow().capabilityIds());for(var entry:c.entries())if(entry.id().startsWith("backup_plan_drafts:")||entry.id().startsWith("inspection_source_collections:")||entry.id().startsWith("inspection_templates:")||entry.id().startsWith("inspection_worksheets:")){assertEquals(true,entry.declaredByRole().get("padmin"));for(String role:List.of("msp","tadmin","viewer"))assertEquals(false,entry.declaredByRole().get(role));}}
}
